export const getRequestSignInCodeUrl = () => {




  return `/v1/auth/code`
}

/**
 * No sign-in required.
 * @summary Send a 6-digit sign-in code by SMS. Same answer whether or not the number has an account. 429 (with Retry-After) during the resend cooldown or past hourly limits. devCode appears only in development
 */
export const requestSignInCode = async (requestSignInCodeBody: RequestSignInCodeBody, options?: Parameters<typeof appFetch>[1]): Promise<requestSignInCodeResponse> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return appFetch<requestSignInCodeResponse>(getRequestSignInCodeUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(requestSignInCodeBody)
  }
);}



